/**
   * @param {object} params
   * @param {string} params.text - What the person typed, verbatim.
   * @param {{ key: string, text: string, check: string }[]} [params.invariants]
   *   Every rule already stored. Without them the model cannot tell an `amend`
   *   from an `add`, and the whole point of the feature is that it tells you
   *   *which* invariants change rather than silently shadowing the old value.
   * @param {{ key: string, value: string }[]} [params.longterm] - Everything in
   *   long-term memory, so the draft is written knowing what it lands beside.
   */
  async propose({ text, invariants = [], longterm = [] } = {}) {
    const startedAt = Date.now();
    const result = await this.#provider.complete({
      model: this.model,
      system: PROPOSER_PROMPT,
      messages: [{ role: "user", content: proposalPrompt(text, invariants, longterm) }],
      temperature: 0,
      maxTokens: this.maxTokens,
    });

    const parsed = parseRows(result?.text);
    return {
      rows: parsed.rows,
      /** What the reply could not be read as — never an empty silence. */
      rejected: parsed.dropped,
      usage: result?.usage ?? { inputTokens: 0, outputTokens: 0 },
      model: result?.model ?? null,
      ms: Date.now() - startedAt,
    };
  }
}

/**
   * The project's rules.
   *
   * An unreadable rule set degrades to *no rules* rather than to a failed
   * turn, which is the same bargain every other store here strikes — and it is
   * worth being explicit that it is the unsafe direction of the two. The block
   * simply is not sent, the answer is unconstrained, and the console says so.
   * The alternative is refusing to answer at all because a file would not
   * parse, which nobody wants and which this app does nowhere else.
   */
  async #loadInvariants() {
    try {
      return await this.invariantStore.load(this.project);
    } catch (err) {
      console.error("[memory] could not read the invariants:", err?.message ?? err);
      return emptyInvariants(this.project);
    }
  }

  async #saveInvariants(record) {
    try {
      await this.invariantStore.save(this.project, record);
    } catch (err) {
      console.error("[memory] could not write the invariants:", err?.message ?? err);
    }
  }

  #extractorFor(provider) {
    if (this.#extractor && this.#cachedFor === null) return this.#extractor;
    this.#rebuild(provider);
    return this.#extractor;
  }

  #promoterFor(provider) {
    if (this.#promoter && this.#cachedFor === null) return this.#promoter;
    this.#rebuild(provider);
    return this.#promoter;
  }

  #brieferFor(provider) {
    if (this.#briefer && this.#cachedFor === null) return this.#briefer;
    this.#rebuild(provider);
    return this.#briefer;
  }

  #proposerFor(provider) {
    if (this.#proposer && this.#cachedFor === null) return this.#proposer;
    this.#rebuild(provider);
    return this.#proposer;
  }

/**
 * The whole record, coerced: usage, messages, and the branch graph.
 *
 * This is the single place a file from any earlier version becomes something
 * the current code can work with. It is called on read and never on write, so
 * an old file is migrated in memory and only takes its new shape the next time
 * something is actually saved to it.
 *
 * @param {object} data
 * @returns {Conversation}
 */
export function normaliseRecord(data) {
  const flat = flatten(data);
